'use strict';
const researchStatus={qualified:'Qualificata',needs_review:'Da approfondire',rejected:'Scartata',unverifiable:'Non verificabile'};
const projectLabels={website:'Sito aziendale',ecommerce:'E-commerce',webapp:'Web app'};
const campaignLabels={running:'Ricerca in corso',waiting:'In attesa del servizio',stopping:'Arresto in corso',paused:'Ricerca sospesa',completed:'Obiettivo raggiunto',exhausted:'Esplorazione completata',blocked:'Ricerca bloccata',error:'Ricerca interrotta per errore'};
let researchFilters={status:'qualified'},researchScope='current',researchOffset=0,researchSequence=0,researchTimer,researchOpportunity=null,researchResultSignature='',researchRequest=null,researchPending=false,campaignBusy=false;
const oldRenderMain=renderMain,oldViewName=viewName,oldGroupCount=groupCount;
groupCount=function(group){if(S?.version?.startsWith('4.'))return S.items.filter(i=>i.qualification==='qualified'&&!i.dismissed_at&&!i.do_not_contact&&(!group||i.contact_group===group)).length;return oldGroupCount(group)};
viewName=function(){return view==='legacy'?'Contatti · Elenco':oldViewName()};
const oldRender=render;
render=function(){const advanced=document.querySelector('.research-advanced')?.open;const preferences={project:$('#campaign-project')?.value,group:$('#campaign-group')?.value,region:$('#campaign-region')?.value};oldRender();if(advanced&&document.querySelector('.research-advanced'))document.querySelector('.research-advanced').open=true;for(const [k,v] of Object.entries(preferences))if(v!==undefined&&$('#campaign-'+k))$('#campaign-'+k).value=v;};
renderMain=function(){
 if(S?.version?.startsWith('4.')&&['overview','all','agencies','direct'].includes(view)){renderResearch();return}
 if(view==='legacy'){$('#main').innerHTML=contactTabs()+header('I tuoi contatti','Le aziende raccolte nelle nuove ricerche. Puoi filtrare per stato e ritrovare anche le proposte eliminate.')+filterUI()+'<div id="results-list"></div>';renderList();return}
 oldRenderMain();if(['pipeline','results'].includes(view))$('#main').insertAdjacentHTML('afterbegin',contactTabs());if(S?.version?.startsWith('4.')&&view==='results')$('#main').insertAdjacentHTML('beforeend',qualitySummary());
};
function campaignActions(c){
 if(c?.running)return `<button class="danger" data-research-action="stop" ${c.status==='stopping'||campaignBusy?'disabled':''}>${c.status==='stopping'?'Arresto in corso…':'Ferma ricerca'}</button>`;
 const resumable=c&&['paused','blocked','error'].includes(c.status);
 return `${resumable?`<button class="primary" data-research-action="resume" ${campaignBusy?'disabled':''}>Riprendi ricerca</button>`:''}<button class="${resumable?'':'primary'}" data-research-action="start" ${campaignBusy?'disabled':''}>${c?'Nuova ricerca':'Avvia ricerca'}</button>`;
}
function inferencePanel(a){const i=a.need_inference;if(!i)return '';const refs=(a.signals||[]).filter(s=>(i.evidence_ids||[]).includes(s.id));return `<section class="panel" data-commercial-inference><h3>Come abbiamo collegato i fatti</h3><span class="tag limitation">Inferenza commerciale · da discutere con l’azienda</span><p>${esc(i.reason)}</p><p><strong>Perché un progetto completo</strong><br>${esc(i.full_project_reason)}</p><p><strong>Alternative più piccole valutate</strong><br>${esc(i.small_fix_reason)}</p>${refs.map(s=>`<p>«${esc(s.quote)}»<br>${link(s.url,'Verifica la fonte')}</p>`).join('')}<p class="small muted">Le citazioni sono fatti dichiarati nelle fonti. Il collegamento è una valutazione commerciale: non dimostra intenzione d’acquisto né budget.</p></section>`}
function investigationPanel(a){const questions=a.investigation_plan||[];if(!questions.length)return '';return `<details class="panel"><summary>Ipotesi da verificare a partire dalle fonti</summary>${questions.map(q=>`<article class="evidence"><span class="tag limitation">Ipotesi, non bisogno accertato</span><p><strong>${esc(q.question)}</strong></p><p>«${esc(q.quote)}»</p>${link(q.url,'Fonte dell’evento')}<p class="small muted">Pubblicato: ${dt(q.published_at)}</p><p>${esc(q.countercheck)}</p><p class="small muted">${esc(q.limit)}</p></article>`).join('')}</details>`}
function campaignActivity(c){return c?`<p class="small muted">Serper: ${c.serper_requests||0} richieste tentate nella campagna.</p>${c.active_research?.hypothesis?`<div class="panel"><strong>${esc(c.active_research.hypothesis.label)}</strong><p>${esc(c.active_research.hypothesis.premise)}</p><p class="small muted">Da provare: ${esc(c.active_research.hypothesis.required_evidence)}</p><p class="small muted">Controprove: ${esc(c.active_research.hypothesis.counterevidence)}</p>${c.active_research.query?`<p>${esc(c.active_research.query)}</p>`:''}</div>`:''}<p class="small muted">In coda: ${c.tasks.pending||0} · In verifica: ${c.tasks.working||0} · Non riuscite: ${c.tasks.failed||0} · Query sospese: ${c.tasks.blocked||0}</p><ol class="research-events">${c.events.slice(0,12).map(e=>`<li><strong>${esc(({decision:'Valutazione',discovery:'Ricerca',error:'Controllo non riuscito',provider_warning:'Fonte parziale',provider_recovered:'Motori disponibili',source:'Fonte',publisher:'Identificazione',excluded:'Esclusione',acquisition_filter:'Filtro pertinenza',planner:'Pianificazione'})[e.kind]||e.kind)}</strong> ${esc(e.message)}${e.url?' · '+link(e.url,'Fonte'):''}</li>`).join('')}</ol>`:'<p class="small muted">Le attività appariranno dopo l’avvio della prima ricerca.</p>'}
function campaignPanel(){const c=S.campaign;return `<section class="campaign-panel" aria-label="Ricerca commerciale"><div class="campaign-title"><div><span class="eyebrow">RICERCA COMMERCIALE <span data-campaign-number>${c?'· CAMPAGNA '+c.id:''}</span></span><h1>La tua prossima opportunità.</h1><p>Aziende da contattare, con una ragione concreta e prove verificabili.</p></div><div class="actions campaign-actions">${campaignActions(c)}</div></div><div class="research-counters">${[['URL scoperti','discovered',c?.discovered||0],['Promettenti','promising',c?.promising||0],['In verifica','verifying',c?.verifying||0],['URL scartati','rejected',c?.funnel?.rejected||c?.rejected||0],['Qualificati','qualified',`${c?.qualified||0} / ${c?.target||50}`]].map(([label,key,value])=>`<div class="counter-${key}"><span>${label}</span><strong data-counter="${key}">${value}</strong></div>`).join('')}</div><p class="small muted"><strong data-target-companies>${c?.target_companies||0}</strong> aziende identificate · promettenti e in verifica contano aziende uniche</p><progress max="${c?.target||50}" value="${Math.min(c?.qualified||0,c?.target||50)}" aria-label="Opportunità qualificate rispetto all’obiettivo"></progress><div class="research-progress" role="status"><strong data-campaign-status>${c?campaignLabels[c.status]:'Pronto per iniziare'}</strong><span data-campaign-message>${esc(c?.message||'Avvia una ricerca. Entrano nei risultati utili solo le aziende che superano tutti i controlli.')}</span><span data-campaign-retry ${c?.next_retry&&c.status==='waiting'?'':'hidden'}>${c?.next_retry?'Prossimo tentativo: '+esc(new Date(c.next_retry).toLocaleTimeString('it-IT')):''}</span></div><details class="research-advanced"><summary>Preferenze e attività della ricerca</summary><p><button class="quiet" data-view="activity">Cronologia delle ricerche →</button></p><div class="research-preferences"><p class="small muted">50 aziende qualificate per campagna. Clienti diretti, richieste freelance e agenzie disponibili a collaborare. I partner senza commessa restano nei promettenti. Le preferenze valgono per una nuova ricerca; Riprendi conserva quelle esistenti.</p><div id="campaign-segments"><strong>Settori inclusi nella ricerca</strong><p>Produttori e piccole aziende B2B<br>Negozi e marchi propri<br>Servizi e professionisti</p></div><p class="small muted">Cerchiamo in tutti e tre i settori, sui siti di aziende e agenzie, nelle pagine Lavora con noi, Jobs e Careers e tra gli annunci freelance indicizzati su LinkedIn. Directory e notizie economiche generiche sono escluse; gli annunci indicizzati richiedono verifica.</p><label>Territorio della nuova ricerca<select id="campaign-region"><option value="Veneto">Veneto · punto di partenza</option><option value="priority">Veneto, Lombardia, Piemonte e Toscana</option><option value="all">Tutte le regioni ammesse</option></select></label><p class="small muted">Esperimento di 30 giorni: registra contatti ed esiti manuali. Puoi ampliare il territorio senza abbassare la qualità.</p><div class="grid2"><label>Progetti da cercare<select id="campaign-project">${options(Object.entries(projectLabels),'website','Tutte le categorie')}</select></label><label>Tipo di cliente<select id="campaign-group">${options([['direct','Clienti diretti'],['agencies','Agenzie e partner']],'','Entrambi')}</select></label></div><p class="small muted">Siti da 2.000 €, e-commerce da 5.000 €: soglie interne, non budget attribuiti alle aziende.</p></div><p class="actions"><button data-discovery-diagnostics>Perché non sto trovando clienti?</button><button data-discovery-metrics>Confronta le strategie →</button></p><div class="campaign-activity">${campaignActivity(c)}</div><details class="source-availability"><summary>Disponibilità delle fonti</summary><div>${c?.sources.map(s=>`<p class="small">${link(s.url,s.region||'Feed')} · ${esc(({available:'Disponibile',unavailable:'Non disponibile',pending:'Da verificare'})[s.state]||s.state)}<br>${esc(s.reason)}</p>`).join('')||'<p class="small muted">Nessuna fonte ancora verificata.</p>'}</div></details></details></section>`}
const researchRegions=['Veneto','Lombardia','Piemonte','Toscana','Emilia-Romagna','Friuli-Venezia Giulia','Trentino-Alto Adige','Liguria',"Valle d’Aosta",'Lazio'];
function renderResearch(){
 const group=['agencies','direct'].includes(view)?view:'';researchResultSignature='';
 $('#main').innerHTML=campaignPanel()+resultTabs()+`<section class="research-results-section" aria-label="Risultati della ricerca"><div class="sectionhead"><div><h2>${group==='agencies'?'Aziende · agenzie e partner':group==='direct'?'Privati · clienti diretti':'Le opportunità selezionate'}</h2><p class="small muted">Solo le aziende qualificate contano verso l’obiettivo.</p></div><button class="quiet" data-view="legacy">Vai ai contatti →</button></div><div class="discovery-tabs" aria-label="Fasi della ricerca"><button data-funnel-view="qualified" class="active">Opportunità qualificate</button><button data-funnel-view="promising">Candidati promettenti</button><button data-funnel-view="all">Aziende esaminate</button></div><div id="discovery-results" hidden></div><div class="filter-box research-filter-box"><div class="filter-heading"><span>Filtra i risultati</span><button class="quiet" data-research-reset>Azzera filtri</button></div><div class="research-filters"><label class="filter-search">Nome o sito<input type="search" data-research-filter="search" value="${esc(researchFilters.search||'')}" placeholder="Cerca un’azienda o un sito"></label><label>Campagna<select data-research-scope><option value="current" ${researchScope==='current'?'selected':''}>Campagna attuale</option><option value="all" ${researchScope==='all'?'selected':''}>Tutte le campagne</option></select></label><label>Qualità<select data-research-filter="status">${options(Object.entries(researchStatus),researchFilters.status,'Tutte le valutazioni')}</select></label><label>Progetto<select data-research-filter="project">${options(Object.entries(projectLabels),researchFilters.project,'Tutti i progetti')}</select></label><label>Area geografica<select data-research-filter="region">${options(researchRegions,researchFilters.region,'Tutte le regioni')}</select></label><label>Stato commerciale<select data-research-filter="stage">${options(Object.entries(S.stages),researchFilters.stage,'Tutti gli stati')}</select></label></div></div><div id="research-results" aria-busy="true"><p class="loading small muted" role="status">Caricamento valutazioni…</p></div></section>`;
 selectResearchPhase(funnelView);
}
function updateResearchState(before){
 const c=S.campaign,old=before.campaign;
 if($('.campaign-panel')){
  for(const [key,value] of Object.entries({discovered:c?.discovered||0,promising:c?.promising||0,verifying:c?.verifying||0,rejected:c?.funnel?.rejected||c?.rejected||0,qualified:`${c?.qualified||0} / ${c?.target||50}`}))$('[data-counter="'+key+'"]').textContent=value;
  $('[data-target-companies]').textContent=c?.target_companies||0;
  const progress=$('.campaign-panel progress');progress.max=c?.target||50;progress.value=Math.min(c?.qualified||0,progress.max);
  $('[data-campaign-number]').textContent=c?'· CAMPAGNA '+c.id:'';
  $('[data-campaign-status]').textContent=c?campaignLabels[c.status]:'Pronto per iniziare';
  $('[data-campaign-message]').textContent=c?.message||'Avvia una ricerca. Entrano nei risultati utili solo le aziende che superano tutti i controlli.';
  const retry=$('[data-campaign-retry]');retry.hidden=!(c?.next_retry&&c.status==='waiting');retry.textContent=c?.next_retry?'Prossimo tentativo: '+new Date(c.next_retry).toLocaleTimeString('it-IT'):'';
  if(c?.status!==old?.status||c?.id!==old?.id)$('.campaign-actions').innerHTML=campaignActions(c);
  if(JSON.stringify(c?.events)!==JSON.stringify(old?.events))$('.campaign-activity').innerHTML=campaignActivity(c);
  if(JSON.stringify(c?.sources)!==JSON.stringify(old?.sources))$('.source-availability > div').innerHTML=c?.sources.map(s=>`<p class="small">${link(s.url,s.region||'Feed')} · ${esc(({available:'Disponibile',unavailable:'Non disponibile',pending:'Da verificare'})[s.state]||s.state)}<br>${esc(s.reason)}</p>`).join('')||'<p class="small muted">Nessuna fonte ancora verificata.</p>';
 }
 const changed=JSON.stringify([c?.funnel,c?.company_funnel,c?.target_companies,c?.id,c?.examined,c?.qualified,c?.rejected,c?.needs_review,c?.unverifiable,S.items])!==JSON.stringify([old?.funnel,old?.company_funnel,old?.target_companies,old?.id,old?.examined,old?.qualified,old?.rejected,old?.needs_review,old?.unverifiable,before.items]);
 researchPending=researchPending||changed;
 if($('#discovery-results')&&!$('#discovery-results').hidden&&changed)loadDiscovery(true);
 if($('#research-results')&&!$('#research-results').hidden&&researchPending&&!$('#detail').open&&!stageSaving&&!$('#research-results').contains(document.activeElement)){researchPending=false;loadResearch()}
 document.querySelectorAll('.sidebar [data-view] .count').forEach(el=>{const id=el.closest('[data-view]').dataset.view;el.textContent=groupCount(id==='all'?null:id)});
}
function linkedCRM(o){return S.items.find(i=>i.company_id===o.company_id||i.id===o.prospect_id||i.member_ids?.includes(o.prospect_id))}
function opportunityCard(o){const a=o.assessment,crm=linkedCRM(o),proof=a.signals[0];return `<article class="card ${crm&&isContacted(crm)?'contacted-card':''}" data-opportunity-id="${o.id}"><div class="card-top"><div class="company"><h3>${esc(o.name)}</h3>${o.website?link(o.website,new URL(o.website).hostname):'<span class="muted">Sito ufficiale non individuato</span>'}<p class="source-meta">${esc(o.region||'Località da verificare')} · ${esc(groupLabels[o.contact_group])}${o.identity?.sector?' · '+esc(o.identity.sector):''}</p>${o.identity?.description?`<p class="small muted" title="Descrizione pubblicata dall’azienda">${esc(o.identity.description)}</p>`:''}</div><div class="score">${o.score}<span>/100</span><small>Priorità</small></div></div><div class="tags"><span class="tag ${o.status==='qualified'?'request':'limitation'}">${researchStatus[o.status]}</span>${projectLabels[o.project]?`<span class="tag">${projectLabels[o.project]}</span>`:''}<span class="tag">Confidenza ${esc(a.confidence)}</span>${a.need_inference?'<span class="tag limitation">Bisogno inferito dalle prove</span>':''}${crm?`<span class="tag">${esc(S.stages[crm.stage])}</span>`:''}</div><p class="reason"><strong>Perché è stata selezionata${o.status==='qualified'?'':' per la verifica'}</strong>${esc(a.why)}</p><div class="grid2"><div><strong>Perché adesso</strong><p>${esc(a.why_now)}</p></div><div><strong>Cosa proporre</strong><p>${esc(a.proposal)}</p></div></div>${o.status!=='qualified'?`<p class="research-limit">${esc(a.reasons[0]||'Verifiche mancanti')}</p>`:''}<div class="cardfooter"><div class="source-meta">${proof?link(proof.url,'Apri la prova originale'):'Nessuna prova commerciale sufficiente'}${proof?'<br>Pubblicazione: '+dt(proof.published_at)+' · Controllo: '+dt(proof.checked_at):''}<br>Budget aziendale: ${a.budget===null?'non dichiarato':money(a.budget)}</div><div class="card-actions"><button data-research-open="${o.id}">Apri dossier →</button>${crm?contactControl(crm)+dismissalControl(crm):''}</div></div></article>`}
async function loadResearch(){
 const box=$('#research-results');if(!box)return;
 clearTimeout(researchTimer);researchRequest?.abort();researchRequest=new AbortController();const sequence=++researchSequence;
 const params=new URLSearchParams({...researchFilters,offset:researchOffset,limit:20});if(['agencies','direct'].includes(view))params.set('group',view);if(researchScope==='current'&&S.campaign)params.set('campaign',S.campaign.id);
 box.setAttribute('aria-busy','true');
 try{
  const response=await fetch('/api/opportunities?'+params,{signal:researchRequest.signal});const data=await response.json();if(!response.ok)throw new Error(data.error||'Impossibile caricare le valutazioni.');
  if(sequence!==researchSequence||box!==$('#research-results')||box.hidden)return;
  updateResearchCounts(data);
  if(researchOffset>=data.total&&researchOffset){researchOffset=Math.max(0,Math.floor((data.total-1)/20)*20);return loadResearch()}
  const signature=JSON.stringify([data,view,researchFilters,researchOffset,S.items.map(i=>[i.id,i.stage,i.contacted_at,i.dismissed_at])]);
  if(signature===researchResultSignature)return;researchResultSignature=signature;
  const filtered=Object.entries(researchFilters).some(([k,v])=>v&&(k!=='status'||v!=='qualified'));
  box.innerHTML=`<p class="result-count small muted" role="status">${data.total} ${researchFilters.status==='qualified'?(data.total===1?'opportunità qualificata':'opportunità qualificate'):(data.total===1?'valutazione':'valutazioni')}${researchScope==='current'?' · Campagna attuale':' · Tutte le campagne'}</p>`+(data.items.length?`<div class="cards">${data.items.map(opportunityCard).join('')}</div><div class="actions pager"><button data-research-page="previous" ${researchOffset?'':'disabled'}>← Precedenti</button><span>${researchOffset+1}–${Math.min(researchOffset+20,data.total)} di ${data.total}</span><button data-research-page="next" ${researchOffset+20>=data.total?'disabled':''}>Successive →</button></div>`:`<div class="empty"><span class="empty-icon" aria-hidden="true">${icon('evidence')}</span><h3>${filtered?'Nessun risultato con questi filtri':researchFilters.status==='qualified'?'Le opportunità migliori richiedono prove solide':'Nessuna valutazione disponibile'}</h3><p>${filtered?'Prova un’altra combinazione o azzera i filtri.':researchFilters.status==='qualified'?'Qui troverai le aziende che hanno superato tutti i controlli. Puoi consultare anche le valutazioni ancora da approfondire.':'Le valutazioni compariranno durante la ricerca, insieme ai motivi di inclusione o esclusione.'}</p><button ${filtered?'data-research-reset':'data-research-show-all'}>${filtered?'Azzera filtri':'Mostra tutte le valutazioni'}</button></div>`);
 }catch(e){if(e.name!=='AbortError'&&sequence===researchSequence&&box===$('#research-results')){researchResultSignature='';box.innerHTML=`<div class="notice" role="alert"><strong>Risultati non disponibili</strong><p>${esc(e.message)}</p><button data-research-retry>Riprova</button></div>`}}
 finally{if(sequence===researchSequence)box.setAttribute('aria-busy','false')}
}
async function researchDetail(id){
 const seq=++detailSequence;const result=await api('/opportunities/'+id);if(seq!==detailSequence)return;current=null;researchOpportunity=result;const o=researchOpportunity,a=o.assessment,crm=linkedCRM(o);
 const d=$('#detail');if(d.contains(toastElement))document.body.append(toastElement);d.innerHTML=`<div class="dialoghead"><div><div class="tags"><span class="tag ${o.status==='qualified'?'request':'limitation'}">${researchStatus[o.status]}</span><span class="tag">Confidenza ${esc(a.confidence)}</span>${a.need_inference?'<span class="tag limitation">Bisogno inferito dalle prove</span>':''}</div><h2 id="detail-title">${esc(o.name)}</h2>${o.website?link(o.website,'Sito ufficiale'):''}</div><button class="quiet" data-close="detail" aria-label="Chiudi dossier">✕</button></div><div class="dialogbody"><p class="reason"><strong>Perché questa azienda</strong>${esc(a.why)}</p><div class="grid2"><section class="panel"><h3>Perché adesso</h3><p>${esc(a.why_now)}</p></section><section class="panel"><h3>Progetto proponibile</h3><p>${esc(a.proposal)}</p><p class="small">Budget dichiarato: ${a.budget===null?'sconosciuto':money(a.budget)}${a.minimum_offer?'<br>Soglia interna del servizio: '+money(a.minimum_offer)+' · non è il budget dell’azienda.':''}</p></section></div><h3>Le prove</h3>${a.signals.map(s=>`<article class="evidence"><span class="tag fact">${esc(({event:'Fatto aziendale',business:'Attività dichiarata',gap:'Carenza dichiarata',condition:'Condizione del canale dichiarata',process:'Processo dichiarato',request:'Richiesta',scope:'Perimetro',counterevidence:'Controprova',budget:'Dato economico',risk:'Rischio'})[s.kind])}</span><p>«${esc(s.quote)}»</p>${link(s.url,'Fonte originale')}<p class="small muted">Pubblicato: ${dt(s.published_at)} · Letto: ${dt(s.checked_at)}</p></article>`).join('')||'<p class="muted">Nessun riscontro commerciale sufficientemente preciso.</p>'}<h3>Ipotesi e obiezioni</h3>${investigationPanel(a)}${inferencePanel(a)}<p class="notice">${esc(a.proposal)}<br><span class="small">Inferenza commerciale: non dimostra intenzione di acquisto.</span></p>${(a.objections||[]).map(v=>'<p>'+esc(v)+'</p>').join('')}${commercialOutcomeForm(null,o.id)}<h3>Prossima azione</h3><p>${esc(a.next_action)}</p><h3>Contatto aziendale</h3>${(o.identity.contacts||[]).map(c=>`<p>${esc(c.value)} · ${link(c.url,'Fonte')}<br><span class="small">${esc(c.role||'Referente non specificato')}</span><br><span class="small muted">${esc(c.basis)}</span></p>`).join('')||'<p class="muted">Nessun canale verificato.</p>'}<details class="panel"><summary>Requisiti obbligatori e verifiche mancanti</summary>${a.gates.map(g=>`<p><strong>${g.passed?'✓':'—'} ${esc(g.label)}</strong><br>${esc(g.reason)}</p>`).join('')}${a.missing.map(v=>`<p class="research-limit">${esc(v)}</p>`).join('')}</details><details class="panel"><summary>Come si forma la priorità: ${a.score}/100</summary>${Object.entries(a.score_detail).map(([label,v])=>`<p><strong>${esc(label)}: ${v.points}</strong><br>${esc(v.reason)}</p>`).join('')}<p class="muted small">Indice operativo, non probabilità di acquisire il cliente.</p></details><details class="panel"><summary>Tutte le pagine esaminate (${o.documents.length})</summary>${o.documents.map(doc=>`<div class="document-source">${link(doc.url,doc.title||doc.url)}<br><span class="small muted">${esc(doc.provider)} · ${dt(doc.checked_at)}</span><details><summary>Estratto conservato</summary><p class="source-excerpt">${esc(doc.text.slice(0,4000))}</p></details></div>`).join('')}</details>${a.technical_report?`<details class="panel"><summary>Lighthouse e SEO: controlli di supporto</summary>${(a.technical_report.pagespeed||[]).map(r=>`<p><strong>${esc(r.strategy)}</strong> · ${r.status==='ok'?Object.entries(r.scores).map(([k,v])=>esc(k)+': '+v+'/100').join(' · '):esc(r.message||'Non disponibile')} ${r.report_url?link(r.report_url,'Report'):''}</p>`).join('')}${(a.technical_report.seo?.checks||[]).map(c=>`<p><strong>${esc(c.label)} · ${esc(c.status)}</strong><br>${esc(c.detail)}</p>`).join('')}<p>${esc(a.technical_report.seo?.geo_aeo?.summary||'')}</p><p class="small muted">Misure di laboratorio; non dimostrano necessità di rifacimento o vendite perse.</p></details>`:''}${crm?`<div class="actions">${contactControl(crm)}<button data-open="${crm.id}">Email, stato e note →</button>${dismissalControl(crm)}</div>`:''}<details class="panel"><summary>Registra una revisione della qualità</summary><form id="quality-review-form" class="stack"><label>Esito<select name="verdict"><option value="confirmed">Confermata dalle fonti</option><option value="false_positive">Falso positivo</option><option value="missed_opportunity">Opportunità utile scartata</option></select></label><label>Motivazione<textarea name="reason" required minlength="5"></textarea></label><button type="submit">Salva revisione</button></form>${o.reviews.map(r=>`<p>${esc(r.verdict)} · ${esc(r.reason)}</p>`).join('')}</details></div>`;
 showDetail();
}
const previousSettingsView=settingsView;
settingsView=function(){if(!S?.version?.startsWith('4.')){previousSettingsView();return}const c=S.settings;$('#main').innerHTML=`<div class="heading"><div><h1>Impostazioni</h1><p>Motore di ricerca, consumi, profilo e territorio.</p></div></div><form id="settings-form" class="stack"><section class="panel"><h2>Profilo</h2><div class="grid2"><label>Nome<input name="name" value="${esc(c.name)}" required></label><label>Località<input name="location" value="${esc(c.location)}"></label><label class="field-wide">Portfolio<input name="portfolio" type="url" value="${esc(c.portfolio)}"></label></div></section><section class="panel"><h2>Serper e analisi</h2><p class="small muted">Chiave: ${S.serper?.configured?'configurata':'non configurata'} · ${S.serper?.requests||0} richieste totali registrate · ${S.serper?.campaign_requests||0} nella campagna attuale.</p>${S.serper?.health?.error?`<p role="status">${esc(S.serper.health.error)}</p>`:''}<details class="model-settings"><summary>Modello di analisi locale</summary><p class="small muted">L’analisi viene eseguita sul tuo Mac tramite Ollama. Nessun servizio a pagamento.</p><label>Nome del modello<input name="ollama_model" value="${esc(c.ollama_model||'qwen2.5:7b')}"></label></details><input type="hidden" name="provider" value="${esc(c.provider)}"><p>${c.provider==='serper'?'Serper · Google. SearXNG e Tavily disattivati. Usa i crediti del tuo account; nessun acquisto automatico.':'SearXNG locale · nessun servizio a pagamento attivo.'} Le letture dei siti non consumano crediti Serper.</p><div class="grid2"><label>Limite volontario giornaliero<input name="daily_api_limit" type="number" min="0" max="100000" value="${c.daily_api_limit??''}" placeholder="Nessun limite"></label><label>Limite volontario mensile<input name="monthly_api_limit" type="number" min="0" max="1000000" value="${c.monthly_api_limit??''}" placeholder="Nessun limite"></label></div><p class="small muted">Serper: ${S.usage.today.serper||0} richieste oggi · ${S.usage.serper_month||0} questo mese. Conteggio locale, non saldo dell’account. Una risposta dalla cache non consuma nuove richieste. Campo vuoto: nessun tetto locale. Zero blocca le richieste. Crediti residui Serper: dato non disponibile; consulta il pannello del provider.</p><p>Siti completi da 2.000 €, e-commerce da 5.000 €. Il budget del cliente rimane sconosciuto finché non è documentato.</p></section><section class="panel"><h2>Territorio</h2><div class="grid2"><label>Località prioritarie<textarea name="preferred_locations">${esc(c.preferred_locations.join('\n'))}</textarea></label><label>Località escluse<textarea name="excluded_locations">${esc(c.excluded_locations.join('\n'))}</textarea></label></div><label class="field-separated">Feed RSS pubblici autorizzati · uno per riga<textarea name="rss_feeds">${esc(c.rss_feeds.join('\n'))}</textarea></label></section><div class="actions"><button class="primary" type="submit">Salva impostazioni</button><button type="button" data-action="backup">Crea backup verificato</button></div></form>`};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-research-reset')||b.hasAttribute('data-research-show-all')){researchFilters=b.hasAttribute('data-research-reset')?{status:'qualified'}:{};if(b.hasAttribute('data-research-reset'))researchScope='current';researchOffset=0;renderMain();$('#research-results').scrollIntoView({block:'nearest'});return}if(b.hasAttribute('data-research-retry')){await loadResearch();return}if(b.dataset.researchOpen){detailOpener={kind:'data-research-open',value:b.dataset.researchOpen};await researchDetail(Number(b.dataset.researchOpen));return}
 if(b.dataset.researchPage){researchOffset=Math.max(0,researchOffset+(b.dataset.researchPage==='next'?20:-20));await loadResearch();$('.research-filter-box')?.scrollIntoView({block:'start'});return}
 if(b.dataset.researchAction)await runCampaignAction(b.dataset.researchAction,b.dataset.campaignId);
 }catch(error){toast(error.message)}});
async function runCampaignAction(action,campaignId){
 if(campaignBusy)return;
 campaignBusy=true;
 const pendingLabel={start:'Avvio della ricerca…',resume:'Ripresa della ricerca…',stop:'Arresto della ricerca…'}[action];
 document.querySelectorAll('[data-research-action],[data-action="research"]').forEach(el=>el.disabled=true);
 const activeButton=document.querySelector('[data-research-action="'+action+'"]');
 if(activeButton)activeButton.textContent=pendingLabel;
 toast(pendingLabel);
 try{
 if(action==='start'){const filters={target:'all'};const project=$('#campaign-project')?.value,group=$('#campaign-group')?.value;if(project)filters.projects=[project];if(group)filters.groups=[group];const territory=$('#campaign-region')?.value||'Veneto';filters.regions=territory==='all'?researchRegions:territory==='priority'?researchRegions.slice(0,4):['Veneto'];S.campaign=await api('/campaigns',{target:50,filters});researchOffset=0;toast('Ricerca avviata. I risultati validati arriveranno progressivamente.')}
 if(action==='stop'){S.campaign=await api('/campaigns/'+S.campaign.id+'/stop',{});toast('Ricerca fermata. Puoi riprendere dal lavoro salvato.')}
 if(action==='resume'){S.campaign=await api('/campaigns/'+(campaignId||S.campaign.id)+'/resume',{});toast('Ricerca ripresa.')}
 await refresh();
 }catch(error){toast(error.message)}finally{
 campaignBusy=false;
 if($('.campaign-actions'))$('.campaign-actions').innerHTML=campaignActions(S.campaign);
 document.querySelectorAll('[data-action="research"]').forEach(el=>el.disabled=false);
 document.querySelectorAll('[data-research-action="resume"][data-campaign-id]').forEach(el=>el.disabled=Boolean(S.campaign?.running));
 }
}
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-research-scope')){researchScope=e.target.value;researchOffset=0;loadResearch();return}const key=e.target.dataset.researchFilter;if(!key)return;researchFilters[key]=e.target.value;researchOffset=0;clearTimeout(researchTimer);researchSequence++;researchRequest?.abort();researchTimer=setTimeout(loadResearch,e.target.tagName==='SELECT'?0:250)});
document.addEventListener('submit',async e=>{if(e.target.id!=='quality-review-form')return;e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;try{await api('/opportunities/'+researchOpportunity.id+'/review',data);await researchDetail(researchOpportunity.id);S=await api('/state');render();toast('Revisione registrata')}catch(error){toast(error.message)}finally{button.disabled=false}},true);
researchDialog=async function(){
 if(campaignBusy)return;
 if(!$('.campaign-panel'))navigate('overview');
 $('.campaign-panel')?.scrollIntoView({block:'start'});
 if(S.campaign?.running){toast('La ricerca è già in corso. Qui puoi seguirne l’avanzamento.');$('[data-research-action="stop"]')?.focus({preventScroll:true});return}
 await runCampaignAction(S.campaign&&['paused','blocked','error'].includes(S.campaign.status)?'resume':'start');
};

const oldActivityView=activityView;
activityView=async function(){
 if(!S?.version?.startsWith('4.')){oldActivityView();return}
 $('#main').innerHTML='<button class="quiet back-link" data-view="overview">← Torna alla ricerca</button><h1>Ricerche e fonti</h1><p class="muted">Campagne salvate: puoi riprendere quelle sospese senza perdere candidati o verifiche.</p><div id="campaign-history">Caricamento…</div>';
 try{const rows=await api('/campaigns');if(view!=='activity')return;
 $('#campaign-history').innerHTML=rows.map(c=>`<details class="panel"><summary>Campagna ${c.id} · ${esc(campaignLabels[c.status])} · ${c.qualified}/${c.target} qualificati</summary><p>${esc(c.message)}</p><p>${c.examined} esaminati · ${c.rejected} scartati · ${c.needs_review+c.unverifiable} da approfondire</p>${!S.campaign?.running&&['paused','blocked','error'].includes(c.status)?`<button data-research-action="resume" data-campaign-id="${c.id}">Riprendi questa campagna</button>`:''}${c.events.map(e=>`<p>${esc(e.message)} ${e.url?link(e.url,'Fonte'):''}</p>`).join('')}</details>`).join('')||'<div class="empty"><h3>La tua ricerca inizia qui</h3><p>Le campagne e le fonti consultate appariranno dopo il primo avvio.</p><button data-view="overview">Vai alla ricerca</button></div>';
}catch(e){if(view==='activity')$('#campaign-history').innerHTML=`<div class="notice" role="alert">${esc(e.message)} <button data-view="activity">Riprova</button></div>`}
};

function rankedQualitySummary(q){
 if(!q.ranked_samples)return '';
 return `<div class="grid2">${[10,20].map(k=>{const sample=q.ranked_samples[String(k)],value=q['precision_at_'+k];return `<div><strong>Prime ${k} proposte · ${value===null?'da verificare':esc(value)+'% confermate'}</strong><p class="small muted">${sample.reviewed}/${k} revisionate · ${sample.available} aziende disponibili. ${sample.false_positives} falsi positivi inclusi.</p></div>`}).join('')}</div><p class="small muted">${esc(q.precision_method)}</p>`;
}
function qualitySummary(){const q=S.research_quality,f=S.commercial_feedback;return `<section class="panel"><h2>Qualità della ricerca</h2><p>${q.reviewed} revisioni registrate · ${q.confirmed} opportunità confermate · ${q.false_positives} falsi positivi.</p><p>${q.sufficient?'Conferme sui risultati proposti: '+q.precision+'%.':'Campione insufficiente: servono almeno 20 opportunità proposte e revisionate.'}</p><p class="small muted">${esc(q.note)}</p>${rankedQualitySummary(q)}<details class="strategy-results"><summary>Esiti per strategia di ricerca</summary><div class="scroll" tabindex="0" role="region" aria-label="Esiti per strategia, tabella scorrevole"><table><thead><tr><th>Strategia</th><th>Contatti</th><th>Risposte</th><th>Clienti</th><th>Risposte / contatti</th></tr></thead><tbody>${f.strategies.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.contacted}</td><td>${r.replied}</td><td>${r.won}</td><td>${r.reply_rate===null?'Campione insufficiente':r.reply_rate+'%'}</td></tr>`).join('')}</tbody></table></div><p class="small muted">${esc(f.note)} Percentuali da ${f.minimum_sample} contatti registrati per strategia.</p></details></section>`}

let funnelView='qualified',funnelSequence=0,funnelOffset=0;
function updateResearchCounts(data){
 const counts=data?.group_counts;
 const phase=funnelView==='promising'?'Candidati promettenti':funnelView==='all'?'Aziende esaminate':researchFilters.status==='qualified'?'Opportunità qualificate':'Valutazioni filtrate';
 document.querySelectorAll('.result-tabs [data-view]').forEach(button=>{
  const group=button.dataset.view;
  const count=counts?(group==='all'?Object.values(counts).reduce((n,v)=>n+v,0):(counts[group]||0)):null;
  button.querySelector('.count').textContent=count===null?'…':count;
  button.querySelector('.count').title=phase;
  if(group==='all')button.querySelector(':scope > span').textContent=phase+' · '+(funnelView!=='qualified'||researchScope==='current'?'campagna attuale':'tutte le campagne');
 });
}
function selectResearchPhase(phase){
 funnelView=phase;
 document.querySelectorAll('[data-funnel-view]').forEach(b=>b.classList.toggle('active',b.dataset.funnelView===phase));
 $('#discovery-results').hidden=phase==='qualified';$('#research-results').hidden=phase!=='qualified';$('.research-filter-box').hidden=phase!=='qualified';
 updateResearchCounts();
 if(phase==='qualified')loadResearch();else loadDiscovery();
}
const funnelLabels={discovered:'Scoperto',promising:'Promettente · da verificare',verifying:'Verifica approfondita',needs_review:'Da approfondire',qualified:'Qualificato',unverifiable:'Non verificabile',rejected:'Scartato'};
const outcomeLabels={interesting:'Interessante',not_relevant:'Non pertinente',contacted:'Contattato',no_reply:'Nessuna risposta',negative_reply:'Risposta negativa',positive_reply:'Risposta positiva',conversation:'Conversazione avviata',quote:'Preventivo richiesto',won:'Cliente acquisito'};
function collaborationSummary(d){
 const c=d.collaboration;if(!c)return '';
 const all=(d.identity?.contacts||[]).filter(x=>['email','form'].includes(x.type));
 const relevant=all.filter(x=>x.type==='email'&&/^(?:jobs?|hr|recruit\w*|candid\w*|collabora\w*|selezion\w*)@/i.test(x.value));
 const general=all.filter(x=>x.type==='email'&&/^(?:info|hello|contact|contatti|office)@/i.test(x.value));
 const contacts=(relevant.length?relevant:general.length?general:all.filter(x=>x.type==='form'||x.url===c.url)).slice(0,3);
 return `<section class="panel"><h4>${esc(c.role||'Richiesta freelance sul sito aziendale')}</h4><blockquote>${esc(c.quote)}</blockquote>${c.contract_quote?`<p><strong>Collaborazione prevista</strong></p><blockquote>${esc(c.contract_quote)}</blockquote>`:''}<p>${link(c.url,c.kind==='standing_invitation'?'Leggi la disponibilità sul sito':'Verifica la richiesta originale')}</p><p><strong>Contatto aziendale</strong><br>${contacts.map(x=>x.type==='email'?esc(x.value):link(x.value,'Modulo aziendale')).join('<br>')||'Canale da verificare'}</p><p class="small muted">Letta il ${dt(c.checked_at)}. ${c.published_at?'Pubblicata il '+dt(c.published_at):'Data di pubblicazione non disponibile.'} ${c.kind==='standing_invitation'?'Disponibilità dichiarata a collaborare; nessuna commessa aperta verificata.':'Disponibilità da confermare con l’azienda.'} Ambito e compenso da concordare; non è un progetto qualificato da 2.000 €.</p></section>`;
}
function commercialOutcomeForm(candidate,assessment){return `<form class="commercial-outcome-form panel" data-candidate="${candidate||''}" data-assessment="${assessment||''}"><h3>Registra un esito reale</h3><p class="small muted">Solo azioni o risposte effettive. Nessun messaggio viene inviato.</p><div class="grid2"><label>Esito<select name="kind">${options(Object.entries(outcomeLabels),'interesting')}</select></label><label>Nota o riscontro<input name="note" maxlength="3000" placeholder="Cosa è successo, quando e perché"></label></div><button type="submit">Salva esito</button><p class="outcome-status small" role="status"></p></form>`}
async function loadDiscovery(background=false){
 const box=$('#discovery-results');if(!box||box.hidden)return;const seq=++funnelSequence;
 const params=new URLSearchParams({limit:20,offset:funnelOffset,company_only:1});if(S.campaign)params.set('campaign',S.campaign.id);if(funnelView==='promising')params.set('state','promising');if(['agencies','direct'].includes(view))params.set('group',view);
 try{const data=await api('/candidates?'+params);if(seq!==funnelSequence||box!==$('#discovery-results')||box.hidden)return;
 updateResearchCounts(data);
 const focused=box.contains(document.activeElement);if(background&&focused)return;
 box.innerHTML=`<p class="small muted">${data.total} ${data.total===1?'azienda identificata':'aziende identificate'} · ${funnelView==='promising'?'Le prove commerciali sono ancora da validare.':'Identità verificata: il bisogno commerciale può essere ancora da dimostrare.'}</p>`+(data.items.length?`<div class="cards">${data.items.map(o=>{const d=o.details;return `<article class="card"><div class="tags"><span class="tag">${esc(d.collaboration?.kind==='standing_invitation'?'Partner disponibile · da contattare':d.collaboration?'Collaborazione freelance · da contattare':funnelLabels[o.state])}</span><span class="tag">${d.publisher?'Fonte editoriale':d.relationship==='partner'?'Partner potenziale':d.company_ready?'Impresa identificata · bisogno da verificare':'Cliente potenziale'}</span></div><h3>${esc(o.name||new URL(o.url).hostname)}</h3>${link(o.url,'Pagina originale')}<p class="reason"><strong>Perché è qui</strong>${esc(o.reason)}</p><p class="small muted">Identità: ${o.identity_status==='verified'?'verificata':'da verificare'} · ${esc(o.region||(d.identity?.regions||[]).join(', ')||'Località da verificare')}<br>Pubblicazione: ${dt(d.published_at)} · Letta: ${dt(d.checked_at)}</p>${d.visit_purpose?`<details><summary>Perché abbiamo visitato questa pagina</summary><p>${esc(d.visit_purpose)}</p>${d.query?`<p class="small">Query: ${esc(d.query)}</p>`:""}${d.access?`<p>${esc(d.access.message)}<br>${esc(d.access.next_action)}</p>`:""}</details>`:""}${collaborationSummary(d)}${d.target_quote?'<p class="small"><strong>Attività riscontrata</strong><br>'+esc(d.target_quote)+'</p>':''}${(d.excerpts||[]).slice(0,1).map(t=>`<blockquote>${esc(t)}</blockquote>`).join('')}<p><strong>Prossimo controllo</strong><br>${esc(d.next_action||'Completare le prove mancanti.')}</p>${o.assessment_id?`<button data-research-open="${o.assessment_id}">Apri dossier →</button>`:''}<details><summary>Esiti e note (${o.outcomes?.length||0})</summary>${(o.outcomes||[]).map(e=>`<p class="small"><strong>${esc(outcomeLabels[e.kind]||e.kind)}</strong> · ${dt(e.created_at)}<br>${esc(e.note)}</p>`).join('')}${commercialOutcomeForm(o.id,o.assessment_id)}</details></article>`}).join('')}</div>`:'<div class="empty"><h3>Nessun candidato in questa fase</h3><p>Qui compaiono le imprese identificate. Le fonti generiche restano nello storico dei controlli.</p></div>')+(data.total>20?`<div class="actions pager"><button data-funnel-page="previous" ${funnelOffset?'':'disabled'}>← Precedenti</button><span>${funnelOffset+1}–${Math.min(funnelOffset+20,data.total)} di ${data.total}</span><button data-funnel-page="next" ${funnelOffset+20>=data.total?'disabled':''}>Successivi →</button></div>`:'');
 }catch(e){box.innerHTML=`<p class="notice" role="alert">${esc(e.message)}</p>`}
}
document.addEventListener('click',async e=>{
 const paging=e.target.closest('[data-funnel-page]');if(paging){funnelOffset=Math.max(0,funnelOffset+(paging.dataset.funnelPage==='next'?20:-20));loadDiscovery();return}
 const phase=e.target.closest('[data-funnel-view]');if(phase){funnelOffset=0;selectResearchPhase(phase.dataset.funnelView);return}
 if(e.target.closest('[data-discovery-metrics]')){if(!S.campaign){toast('Avvia una ricerca per raccogliere le prime misure.');return}try{const m=await api('/campaigns/'+S.campaign.id+'/metrics');const d=$('#detail');if(d.contains(toastElement))document.body.append(toastElement);d.innerHTML=`<div class="dialoghead"><h2 id="detail-title">Esperimento · 30 giorni</h2><button class="quiet" data-close="detail" aria-label="Chiudi metriche">✕</button></div><div class="dialogbody"><p>${esc(m.note)}</p><p>Fine osservazione: ${dt(m.ends_at)}. La ricerca resta controllata da Avvia e Stop.</p><div class="scroll" tabindex="0" role="region" aria-label="Metriche per strategia"><table><thead><tr><th>Strategia</th><th>Fonti lette</th><th>Scoperti</th><th>Aziende</th><th>Passati a promettente</th><th>Qualificati</th><th>Non verificabili</th><th>Secondi</th><th>Contatti</th><th>Risposte</th><th>Positive</th><th>Conversazioni</th><th>Preventivi</th><th>Clienti</th></tr></thead><tbody>${m.strategies.map(r=>`<tr><td>${esc(r.label)}</td>${['sources','discovered','companies','promising','qualified','unverifiable','seconds','contacted','replied','positive_reply','conversation','quote','won'].map(k=>`<td>${r[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">Le metriche commerciali provengono dagli esiti manuali. Un campione piccolo non consente conclusioni sull’efficacia del canale.</p></div>`;showDetail()}catch(err){toast(err.message)}}
});
document.addEventListener('submit',async e=>{if(!e.target.matches('.commercial-outcome-form'))return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),data=Object.fromEntries(new FormData(form));if(button.disabled)return;button.disabled=true;if(form.dataset.candidate)data.candidate_id=Number(form.dataset.candidate);else data.assessment_id=Number(form.dataset.assessment);try{await api('/commercial-outcomes',data);form.querySelector('.outcome-status').textContent='Esito salvato nello storico.';S=await api('/state');toast('Esito commerciale registrato')}catch(err){form.querySelector('.outcome-status').textContent=err.message}finally{button.disabled=false}},true);

async function discoveryDiagnostics(){
 if(!S.campaign){toast('Avvia una ricerca per raccogliere le misure.');return}
 const seq=++detailSequence;
 const d=await api('/campaigns/'+S.campaign.id+'/diagnostics');if(seq!==detailSequence)return;
 const panel=$('#detail');if(panel.contains(toastElement))document.body.append(toastElement);
 const table=(rows,label)=>`<div class="scroll" tabindex="0" role="region" aria-label="${esc(label)}"><table><thead><tr><th>${esc(label)}</th><th>Query</th><th>Richieste Serper</th><th>Pagine lette</th><th>Da cache</th><th>URL nuovi</th><th>Aziende verificate</th><th>Promettenti attuali</th><th>Qualificati</th><th>Errori</th><th>Secondi</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td>${['queries','credits','pages','cached_pages','unique_urls','companies','promising','qualified','errors','seconds'].map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 panel.innerHTML=`<div class="dialoghead"><div><h2 id="detail-title">Perché non sto trovando clienti?</h2><p class="small muted">Misure della campagna ${S.campaign.id} · aggiornate all’apertura</p></div><button class="quiet" data-close="detail" aria-label="Chiudi diagnostica">✕</button></div><div class="dialogbody stack"><p>${esc(d.note)}</p><section class="panel"><h3>Disponibilità del motore</h3><p>${d.health.error?esc(d.health.error):d.health.last_success?'Ultima risposta riuscita: '+dt(d.health.last_success):'Motore selezionato non ancora verificato.'}</p>${d.health.retry_at?`<p>Nuovo tentativo consentito dal ${esc(new Date(d.health.retry_at).toLocaleString('it-IT'))}. Possono continuare le verifiche sui siti aziendali già trovati.</p>`:''}<p>${d.paid.serper.enabled?'Serper attivo · '+(d.paid.serper.daily_request_limit==null?'nessun tetto giornaliero locale':d.paid.serper.daily_request_limit+' richieste al giorno')+'. SearXNG e Tavily disattivati. Nessuna ricarica automatica.':'Serper e Tavily disattivati.'}</p></section><div class="grid2"><section class="panel"><h3>Esiti delle query</h3><p>${d.queries.empty} senza URL nuovi · ${d.queries.unproductive} senza riscontri pertinenti · ${d.queries.awaiting_verification} in attesa della lettura delle fonti.</p></section><section class="panel"><h3>Esplorazione progressiva</h3><p>${d.branches.filter(b=>b.state==='active').length} rami attivi · ${d.branches.filter(b=>b.state==='paused').length} sospesi. Un blocco tecnico non dimostra assenza di opportunità.</p></section></div><section class="panel"><h3>Percorso dei risultati</h3><p class="small muted">Query, motivo della visita, decisione e azienda identificata. Sono inclusi gli URL esclusi prima del download.</p><div id="research-paths"><button data-research-paths="0">Mostra i percorsi</button></div></section><h3>Fonti di acquisizione e letture</h3>${table(d.providers,'Provider')}<details class="panel"><summary>Dettaglio per strategia</summary>${table(d.strategies,'Strategia')}</details><details class="panel"><summary>Motivi degli scarti e delle pause</summary>${d.strategies.map(r=>Object.entries(r.rejections).map(([reason,n])=>`<p>${esc(reason)} <strong>(${n})</strong></p>`).join('')).join('')||'<p>Nessuno scarto misurato.</p>'}${d.branches.filter(b=>b.reason).map(b=>`<p><strong>${esc(b.strategy)} · ${esc(b.region)}</strong><br>${esc(b.reason)}</p>`).join('')}</details><details class="panel"><summary>Catalogo delle fonti (${d.sources.length})</summary>${d.sources.map(s=>`<p>${link(s.url,s.region||new URL(s.url).hostname)} · ${esc(s.kind)} · ${esc(s.state)}<br><span class="small muted">${esc(s.reason)} ${s.last_success?'Ultimo accesso riuscito: '+dt(s.last_success):''}</span></p>`).join('')}</details></div>`;
 showDetail();
}
document.addEventListener('click',async e=>{if(e.target.closest('[data-discovery-diagnostics]')){try{await discoveryDiagnostics()}catch(error){toast(error.message)}}});

async function loadResearchPaths(offset){
 const box=$('#research-paths');if(!box||!S.campaign)return;
 const cid=S.campaign.id;box.setAttribute('aria-busy','true');
 try{const data=await api('/campaigns/'+cid+'/paths?offset='+offset+'&limit=10');if(box!==$('#research-paths'))return;
 box.innerHTML=`<p class="small muted">${esc(data.note)}</p>`+data.items.map(p=>`<details class="panel"><summary>${esc(p.classification)} · ${esc(new URL(p.url).hostname)}</summary><p><strong>Query</strong><br>${esc(p.query||'Collegamento da una fonte; query non registrata')}</p>${p.root_query&&p.root_query!==p.query?`<p class="small">Ricerca iniziale: ${esc(p.root_query)}</p>`:''}<p><strong>Informazione cercata</strong><br>${esc(p.purpose)}</p><p>${link(p.url,'URL esaminato')}${p.source_url&&p.source_url!==p.url?' · '+link(p.source_url,'Fonte di partenza'):''}</p><p><strong>Decisione</strong><br>${esc(p.reason)}</p>${p.access?`<p class="small">Accesso: ${esc(p.access.code)} · ${esc(p.access.message)}</p>`:''}<p>Azienda: ${esc(p.company||p.subject||'Non identificata')}<br>Qualificazione: ${esc(funnelLabels[p.qualification]||'Non qualificata')}</p>${p.assessment_id?`<button data-research-open="${p.assessment_id}">Apri dossier</button>`:''}</details>`).join('')+`<div class="actions pager"><button data-research-paths="${Math.max(0,data.offset-data.limit)}" ${data.offset?'':'disabled'}>Precedenti</button><span>${data.total?data.offset+1:0}–${Math.min(data.offset+data.limit,data.total)} di ${data.total}</span><button data-research-paths="${data.offset+data.limit}" ${data.offset+data.limit>=data.total?'disabled':''}>Successivi</button></div>`;
 }finally{box.removeAttribute('aria-busy')}
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-research-paths]');if(button){try{await loadResearchPaths(Number(button.dataset.researchPaths))}catch(error){toast(error.message)}}});
